import{z as d,x as p,o as n,c as A,q as s,j as i,D as e,d as o,s as t,S as E,b as r}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"家族企业与金字塔","description":"","frontmatter":{"title":"家族企业与金字塔","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/family-firms-pyramids.md","filePath":"econ/family-firms-pyramids.md","lastUpdated":1791413859000}'),m={name:"econ/family-firms-pyramids.md"};function f(h,a,B,C,c,u){const l=p("Mermaid");return n(),A("div",null,[a[2]||(a[2]=s('<h1 id="家族企业与金字塔" tabindex="-1">家族企业与金字塔 <a class="header-anchor" href="#家族企业与金字塔" aria-label="Permalink to &quot;家族企业与金字塔&quot;">​</a></h1><div class="epigraph"><p>投票权与现金流权分离之后，控制人可以用少数资本指挥多数资产。这是所有权结构，不是企业文化小品。</p><footer>—— La Porta, Lopez-de-Silanes, Shleifer and Vishny 的所有权与法律；Almeida and Wolfenzon 的金字塔</footer></div><p><a href="/econ/esg-theory">上一课</a>问目标函数里有没有非金钱项。缺口是控制权：谁能决定目标。本课钉家族与金字塔，识别课收束本课程。不重写 <a href="/econ/modigliani-miller">MM</a> 资本结构。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LLSV：许多国家的典型企业不是 Berle–Means 的分散股东，而是家族或国家通过金字塔、交叉持股维持控制。Almeida–Wolfenzon：金字塔便于用内部资本市场配置，也便于掏空。若公司金融实证默认「股东价值最大化的公众公司」，外部有效性只覆盖一种所有权。缺口是把现金流权（C）与投票权（V）分开，隧道（tunneling）是 \\(V\\gt C\\) 时的代理。</p><p>分离靠乘法。控制链上投票权相乘，现金流权也相乘，缺口随层数放大：Johnson 等人的标准例子，三层各持 50%，控制人对底层公司的现金流权是 \\(0.5^3=12.5\\%\\)，投票权仍是 100%——用八分之一的现金，指挥全部资产。数字在东亚样本里更细：Claessens, Djankov and Lang 看 9 个经济体、2,980 家公司，近三分之二有单一控制股东，家族平均现金流权约 15.7%，投票权约 19.8%，缺口靠金字塔与交叉持股放大。LLSV 跨 27 国的对照：好保护经济体外，多数国家的典型大企业有最终控制人，金字塔是常规工具而非奇观。</p><p><span class="marginnote">Claessens, Djankov and Lang 的东亚金字塔：现金流权均值 15.7%，投票权 19.8%。Johnson, La Porta, Lopez-de-Silanes and Shleifer 的掏空算术：\\(V\\gt C\\) 越大，转移一美元留给自己越多。Burkart, Panunzi and Shleifer 的家族控制权权衡：家族经理人能力弱但与控制人利益一致、监督强；职业经理人能力强但代理重。</span></p><p><span class="marginnote">术语翻译：现金流权是「赚了钱你能分几成」，投票权是「开董事会时你说了几分」。教科书里的分散持股公司两者基本重合；金字塔把二者拆开——投票权沿控制链一级级传下去，现金流权却被逐层乘法稀释。缺口 \\(V-C\\) 就是「说话的份」超出「分钱的份」的部分。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>度量：控制链上的投票乘积 vs 现金流乘积。后果：股利、关联交易、职业经理人聘任、危机时的支持（propping）与掏空。与双层股权：同是 \\(V\\neq C\\)，但<a href="/econ/dual-class-shares">双层股权</a>在同一公司内做分离，金字塔把分离做到集团层面、跨多家公司。法律：投资者保护弱则金字塔更有价值（LLSV，见<a href="/econ/law-and-finance">法律与金融</a>）。与 ESG：控制人偏好可以是王朝、声誉或政治，不必是评级。</p>',10)),(n(),i(E,null,{default:e(()=>[t(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E7%8E%B0%E9%87%91%E6%B5%81%E6%9D%83%22%5D%20--%3E%20ALIGN%5B%22%E6%BF%80%E5%8A%B1%22%5D%0A%20%20V%5B%22%E6%8A%95%E7%A5%A8%E6%9D%83%22%5D%20--%3E%20CTRL%5B%22%E6%8E%A7%E5%88%B6%22%5D%0A%20%20GAP%5B%22V%20%3E%20C%22%5D%20--%3E%20TUN%5B%22%E6%8E%8F%E7%A9%BA%E9%A3%8E%E9%99%A9%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[o("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"内部资本市场在外部融资贵时有收益；控制权私人收益在保护弱时有成本。金字塔的融资逻辑（Almeida–Wolfenzon）：家族把成熟企业的现金流向上集中到直接持有的母公司，把新项目压在塔底，用塔底外部股东的钱分担创业风险——内部资本市场替不完善的外部市场干活。代理成本在同一构造里：\\(V\\gt C\\) 时，把价值从分离度低的公司搬到分离度高的公司有利可图，重排现金流本身就是私利。",-1)),(n(),i(E,null,{default:e(()=>[t(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAM%5B%22%E5%AE%B6%E6%97%8F%22%5D%20--%3E%7C%22%E6%8A%95%E7%A5%A8%2050%25%22%7C%20A%5B%22%E7%94%B2%E5%85%AC%E5%8F%B8%20%E5%AE%B6%E6%97%8F%E7%9B%B4%E6%8E%A5%E6%8C%81%E6%9C%89%22%5D%0A%20%20A%20--%3E%7C%22%E6%8A%95%E7%A5%A8%2050%25%22%7C%20B%5B%22%E4%B9%99%E5%85%AC%E5%8F%B8%22%5D%0A%20%20B%20--%3E%7C%22%E6%8A%95%E7%A5%A8%2050%25%22%7C%20C%5B%22%E4%B8%99%E5%85%AC%E5%8F%B8%20%E5%A1%94%E5%BA%95%22%5D%0A%20%20EXT%5B%22%E5%A1%94%E5%BA%95%E5%A4%96%E9%83%A8%E5%B0%8F%E8%82%A1%E4%B8%9C%22%5D%20--%3E%20C%0A%20%20FAM%20-.-%3E%7C%22%E7%8E%B0%E9%87%91%E6%B5%81%E6%9D%83%200.5%20%C3%97%200.5%20%C3%97%200.5%20%3D%2012.5%25%22%7C%20C%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p><span class="marginnote">数字实例：塔底的丙公司价值 100，控制人的现金流权只有 12.5%。把 10 元价值掏进自己腰包，按持股本该只分到 1.25 元，却实拿 10 元——损失的大头由塔底外部股东埋单。缺口 \\(V-C\\) 越大，这笔账越划算，掏空不是道德失足，是激励几何。</span></p><p>掏空不需要盗。关联交易定价、给关联方放信用、薪资与咨询费、定向增发给控制人家族，都是隧道；意大利 Parmalat 在 2003 年被揭出近 40 亿欧元的伪造银行存款，多年盈利是账面戏法，资金沿关联路径漏出。支持是同一控制权的另一状态：1997–98 危机里，韩国财阀把私产注入濒危关联企业续命——前 30 大财阀的平均负债权益比在 1997 年底已近五倍，不救就集体穿仓——Friedman, Johnson and Mitton 把支持读成期权的执行：公司活着，控制权期权才在；公司死了，私人收益归零。事前看是掏空倾向的结构，危机里可以整体翻成支持：同一 \\(V-C\\) 缺口，两个方向的现金流。</p><p>均衡所有权结构随法律与资本市场深度变：保护弱、市场浅，金字塔次优且普遍；保护强、市场深，分散化上市占优。危机中，控制人可能用私产支持（propping），因为控制权期权还在——这不是利他，是期权价值。</p><p><span class="marginnote">常见误区：把 1998 年财阀「自掏腰包救关联企业」读成良心发现。控制人不是在行善——公司活着，控制权带来的私人收益和期权才继续值钱；公司清算，一切归零。同一个结构，平时往里掏空、危机时往里输血，两个方向都不需要利他假设就能解释。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把家族写成低效的代名词：法律弱、市场浅时，金字塔是次优合同，不是人格缺陷。下一课：这些结构使 IV 更难，识别要声明谁在最大化什么。不写某姓氏企业史。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>把投票权与现金流权分开，金字塔是分离的常见技术。</li><li>东亚样本：现金流权约 15.7% 对投票权约 19.8%；三层各持半数即 12.5% 对 100%。</li><li>掏空与支持是同一控制权的两个状态：Parmalat 是隧道，1998 的财阀是期权执行。</li><li>出处：LLSV；Almeida and Wolfenzon；Claessens–Djankov–Lang；Johnson 等掏空。</li></ul>',8))])}const V=d(m,[["render",f]]);export{D as __pageData,V as default};
